fn triangle(t: i32, span: i32) -> i32 {
    let period: i32 = span * 2;
    let phase: i32 = t % period;
    if phase < span { phase } else { period - phase }
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    host::display::clear(0x000000);
    host::display::fill_rect(0, 0, w, 2, 0x404040);
    host::display::fill_rect(0, h - 2, w, 2, 0x404040);
    host::display::fill_rect(0, 0, 2, h, 0x404040);
    host::display::fill_rect(w - 2, 0, 2, h, 0x404040);
    let bx: i32 = 2 + triangle(t * 3, w - 20);
    let by: i32 = 2 + triangle(t * 2, h - 20);
    host::display::fill_rect(bx, by, 16, 16, 0xffffff);
    host::display::present();
}
